import { Engine } from './core/engine.js';
import { createConfig } from './core/config.js';

import { RenderSystem } from './render/index.js';
import { MaterialSystem } from './materials/index.js';
import { SkySystem } from './sky/index.js';
import { WorldSystem } from './world/index.js';
import { PhysicsSystem } from './physics/index.js';
import { PlayerSystem } from './player/index.js';
import { WeaponSystem } from './weapons/index.js';
import { FxSystem } from './fx/index.js';
import { AiSystem } from './ai/index.js';
import { UiSystem } from './ui/index.js';
import { AudioSystem } from './audio/index.js';

import { installShotApi } from './dev/shots.js';
import { prewarm } from './core/prewarm.js';

const QUALITY_NAMES = ['low', 'medium', 'high', 'ultra'];
const QUALITY_TRANSITION_KEY = 'overwatch:quality-transition';

function consumeQualityTransition() {
  try {
    const raw = sessionStorage.getItem(QUALITY_TRANSITION_KEY);
    sessionStorage.removeItem(QUALITY_TRANSITION_KEY);
    if (!raw) return null;
    const value = JSON.parse(raw);
    if (
      !value ||
      !QUALITY_NAMES.includes(value.quality) ||
      !Number.isFinite(value.at) ||
      Date.now() - value.at > 30_000
    ) return null;
    return value;
  } catch {
    return null;
  }
}

const params = new URLSearchParams(location.search);
const capture = params.get('capture') === '1';
// Deterministic shutter for the pixel gate: the engine does not schedule its own
// frames, the driver advances exactly N of them through window.__PUMP__. Opt-in,
// because tools that measure real frame pacing (tools/perf.mjs) need the loop to
// free-run. See the long comment in src/dev/shots.js.
const lockstep = capture && params.get('lockstep') === '1';

const prewarmParam = params.get('prewarm');
const prewarmMode =
  prewarmParam === '1' || prewarmParam === 'full'
    ? 'full'
    : prewarmParam === '0' || prewarmParam === 'off'
      ? 'off'
      : capture
        ? 'full'
        : 'off';

const storedQualityTransition = consumeQualityTransition();
const qualityTransition =
  !capture && storedQualityTransition?.quality === params.get('q')
    ? storedQualityTransition
    : null;
const restoredSettings = {};
if (Number.isFinite(qualityTransition?.settings?.sensitivity)) {
  restoredSettings.sensitivity = qualityTransition.settings.sensitivity;
}
if (Number.isFinite(qualityTransition?.settings?.fov)) {
  restoredSettings.fov = Math.max(65, Math.min(120, qualityTransition.settings.fov));
}
if (typeof qualityTransition?.settings?.invertY === 'boolean') {
  restoredSettings.invertY = qualityTransition.settings.invertY;
}

// Preserve the established ultra capture baseline while normal play uses the
// safe production default from config.js. Every quality remains URL-selectable.
const config = createConfig({
  ...(params.has('q') ? { quality: params.get('q') } : capture ? { quality: 'ultra' } : {}),
  ...restoredSettings,
  deterministic: capture,
  prewarm: prewarmMode,
});

const canvas = document.getElementById('game');
const boot = document.getElementById('boot');
const bootStatus = document.getElementById('boot-status');
const bootActivity = document.getElementById('boot-activity');
const bootPercent = document.getElementById('boot-percent');
const bootTrack = document.getElementById('boot-track');
const bootProgress = document.getElementById('boot-progress');
const bootDetail = document.getElementById('boot-detail');
const bootSteps = document.getElementById('boot-steps');

const BOOT_LABEL = {
  render: 'Renderer und Renderziele',
  materials: 'Materialien und Texturen',
  sky: 'Himmel und Beleuchtung',
  physics: 'Physik',
  world: 'Weltgeometrie',
  player: 'Spieler',
  weapons: 'Waffen',
  fx: 'Effekte',
  ai: 'Gegner und Navigation',
  ui: 'Benutzeroberfläche',
  audio: 'Audio',
  prewarm: 'Shader vorbereiten',
  'first-frame': 'Ersten Frame darstellen',
};
const BOOT_STATE_LABEL = {
  pending: 'Ausstehend',
  current: 'Wird vorbereitet',
  done: 'Bereit',
  skipped: 'Übersprungen',
  error: 'Fehler',
};
const BOOT_STATE_CLASSES = Object.keys(BOOT_STATE_LABEL).map((state) => `is-${state}`);
const QUALITY_LABEL = {
  low: 'Niedrig · schneller Start',
  medium: 'Mittel',
  high: 'Hoch',
  ultra: 'Ultra',
};
const bootProfile = `Qualität: ${QUALITY_LABEL[config.quality] ?? config.quality} · WebGL 2`;
const bootStepElements = new Map();
let activeBootStepId = null;
let bootProgressValue = 0.02;

for (const item of bootSteps?.querySelectorAll('[data-boot-step]') ?? []) {
  item.dataset.bootState = 'pending';
  bootStepElements.set(item.dataset.bootStep, item);
}

function ensureBootStep(id, label = BOOT_LABEL[id] ?? id) {
  let item = bootStepElements.get(id);
  if (item || !bootSteps || !id) return item ?? null;

  item = document.createElement('li');
  item.className = 'boot-step is-pending';
  item.dataset.bootStep = id;
  item.dataset.bootState = 'pending';

  const marker = document.createElement('span');
  marker.className = 'boot-step-marker';
  marker.setAttribute('aria-hidden', 'true');
  const name = document.createElement('span');
  name.className = 'boot-step-label';
  name.textContent = label;
  const state = document.createElement('span');
  state.className = 'boot-step-state';
  state.textContent = BOOT_STATE_LABEL.pending;
  item.append(marker, name, state);

  // Unknown future subsystems still appear before the two terminal boot steps.
  const terminalStep = bootSteps.querySelector('[data-boot-step="prewarm"], [data-boot-step="first-frame"]');
  bootSteps.insertBefore(item, terminalStep);
  bootStepElements.set(id, item);
  return item;
}

function setBootStep(id, state, { ms, stateText } = {}) {
  const item = ensureBootStep(id);
  if (!item || !BOOT_STATE_LABEL[state]) return;

  if (state === 'current' && activeBootStepId && activeBootStepId !== id) {
    const previous = bootStepElements.get(activeBootStepId);
    if (previous?.dataset.bootState === 'current') {
      previous.classList.remove('is-current');
      previous.classList.add('is-pending');
      previous.dataset.bootState = 'pending';
      const previousState = previous.querySelector('.boot-step-state');
      if (previousState) previousState.textContent = BOOT_STATE_LABEL.pending;
      previous.removeAttribute('aria-current');
    }
  }

  item.classList.remove(...BOOT_STATE_CLASSES);
  item.classList.add(`is-${state}`);
  item.dataset.bootState = state;

  const duration = state === 'done' && Number.isFinite(ms) && ms > 50 ? ` · ${Math.round(ms)} ms` : '';
  const stateElement = item.querySelector('.boot-step-state');
  if (stateElement) stateElement.textContent = `${stateText ?? BOOT_STATE_LABEL[state]}${duration}`;

  if (state === 'current') {
    activeBootStepId = id;
    item.setAttribute('aria-current', 'step');
    item.scrollIntoView?.({ block: 'nearest' });
  } else {
    item.removeAttribute('aria-current');
    if (activeBootStepId === id) activeBootStepId = null;
  }
}

function setBoot(text, progress = bootProgressValue, detail = bootProfile, activity) {
  const numericProgress = Number(progress);
  if (Number.isFinite(numericProgress)) {
    bootProgressValue = Math.max(bootProgressValue, Math.max(0, Math.min(1, numericProgress)));
  }
  const percent = Math.round(bootProgressValue * 100);

  if (bootStatus) bootStatus.textContent = text;
  if (bootActivity && typeof activity === 'string') bootActivity.textContent = activity;
  if (bootPercent) bootPercent.textContent = `${percent}%`;
  if (bootProgress) bootProgress.style.width = `${percent}%`;
  if (bootDetail && detail != null) bootDetail.textContent = detail;
  if (bootTrack) {
    bootTrack.setAttribute('aria-valuenow', String(percent));
    bootTrack.setAttribute('aria-valuetext', `${percent} Prozent – ${text}`);
  }
}

function showBootError(err, stepId = activeBootStepId) {
  const message = String(err?.message ?? err ?? 'Unbekannter Fehler');
  if (stepId) setBootStep(stepId, 'error');
  if (boot) {
    boot.classList.add('has-error');
    boot.setAttribute('role', 'alert');
    boot.setAttribute('aria-live', 'assertive');
    boot.setAttribute('aria-busy', 'false');
  }
  bootTrack?.setAttribute('aria-invalid', 'true');
  setBoot(
    'Start fehlgeschlagen',
    bootProgressValue,
    'Offene Schritte bleiben ausstehend',
    `Der Start wurde angehalten: ${message}`
  );
}

let qualityReloadStarted = false;
function beginQualityReload(name) {
  if (!QUALITY_NAMES.includes(name)) return false;
  if (qualityReloadStarted) return true;
  if (name === config.quality) return false;
  qualityReloadStarted = true;

  const label = QUALITY_LABEL[name] ?? name;
  const nextUrl = new URL(location.href);
  nextUrl.searchParams.set('q', name);

  try {
    sessionStorage.setItem(QUALITY_TRANSITION_KEY, JSON.stringify({
      quality: name,
      at: Date.now(),
      returnToMenu: true,
      settings: {
        sensitivity: config.sensitivity,
        fov: config.fov,
        invertY: config.invertY,
      },
    }));
  } catch {
    // Storage may be disabled; the query parameter still makes reload reliable.
  }

  bootProgressValue = 0.04;
  activeBootStepId = null;
  if (boot) {
    boot.style.display = 'grid';
    boot.classList.remove('is-hidden', 'has-error');
    boot.classList.add('is-reloading');
    boot.setAttribute('role', 'status');
    boot.setAttribute('aria-live', 'polite');
    boot.setAttribute('aria-busy', 'true');
    boot.querySelector('.boot-card')?.scrollTo?.(0, 0);
  }
  bootTrack?.removeAttribute('aria-invalid');
  setBoot(
    `Grafikprofil „${label}“ wird geladen …`,
    0.08,
    `Zielprofil: ${label} · Neustart`,
    'Die aktuelle Szene wird sicher beendet. Anschließend startet das Spiel mit der neuen Grafik.'
  );

  let navigationStarted = false;
  const navigate = () => {
    if (navigationStarted) return;
    navigationStarted = true;
    try {
      location.replace(nextUrl.href);
    } catch (err) {
      qualityReloadStarted = false;
      showBootError(err);
    }
  };
  requestAnimationFrame(() => {
    setBoot(
      'Spiel wird neu geladen …',
      0.14,
      `Zielprofil: ${label} · Neustart`,
      'Die Grafikeinstellung wurde gespeichert. Der Systemstart beginnt sofort.'
    );
    setTimeout(navigate, 140);
  });
  // Background tabs may throttle rAF; never leave the transition hanging.
  setTimeout(navigate, 800);
  return true;
}

function completeBootProgress() {
  setBootStep('first-frame', 'done');
  if (boot) boot.setAttribute('aria-busy', 'false');
  setBoot('Start abgeschlossen', 1, bootProfile, 'Das Spiel ist bereit.');
}

function finishBoot(immediate = false) {
  if (!boot) return;
  if (immediate) {
    boot.style.display = 'none';
    return;
  }
  boot.classList.add('is-hidden');
  setTimeout(() => { boot.style.display = 'none'; }, 220);
}

if (boot) boot.setAttribute('aria-busy', 'true');
setBoot(
  qualityTransition
    ? `Grafikprofil „${QUALITY_LABEL[config.quality] ?? config.quality}“ wird gestartet …`
    : 'Systemstart wird vorbereitet …',
  0.02,
  bootProfile,
  qualityTransition
    ? 'Das Spiel wurde für den Grafikwechsel neu geladen. Die Systeme werden jetzt vorbereitet.'
    : 'Der Start beginnt gleich. Alle Schritte sind noch ausstehend.'
);

// Ensure the static loading UI gets one paint before any procedural generation.
if (!capture) await new Promise((resolve) => requestAnimationFrame(() => resolve()));

const engine = new Engine({ canvas, config });
engine.events.on('ui:quality-request', (request) => {
  if (!request || request.handled) return;
  request.handled = beginQualityReload(request.quality);
});

// Registration order is irrelevant — Registry topo-sorts on static deps.
engine
  .add(RenderSystem)
  .add(MaterialSystem)
  .add(SkySystem)
  .add(WorldSystem)
  .add(PhysicsSystem)
  .add(PlayerSystem)
  .add(WeaponSystem)
  .add(FxSystem)
  .add(AiSystem)
  .add(UiSystem)
  .add(AudioSystem);

let shotApi;
let warmup;
try {
  await engine.init({
    yieldBetween: !capture,
    onProgress: ({ id, index, total, phase, progress, ms }) => {
      const label = BOOT_LABEL[id] ?? id;
      const mappedProgress = Number.isFinite(progress) ? 0.04 + progress * 0.76 : bootProgressValue;

      if (phase === 'start') {
        setBootStep(id, 'current');
        const position = Number.isInteger(index) && Number.isInteger(total)
          ? `Schritt ${index + 1} von ${total}.`
          : 'Dieser Startschritt ist aktiv.';
        setBoot(
          `${label} wird vorbereitet …`,
          mappedProgress,
          bootProfile,
          `${position} Bitte kurz warten.`
        );
      } else if (phase === 'done') {
        setBootStep(id, 'done', { ms });
        const duration = Number.isFinite(ms) && ms > 50 ? ` (${Math.round(ms)} ms)` : '';
        setBoot(
          `${label} ist bereit${duration}`,
          mappedProgress,
          bootProfile,
          `${label} ist abgeschlossen. Der nächste Schritt beginnt automatisch.`
        );
      }
    },
  });

  shotApi = installShotApi(engine, { capture, lockstep });

  // A graphics change returns to the settings menu after the fresh renderer has
  // reached its first frame. Keeping the menu paused also preserves user intent.
  if (qualityTransition?.returnToMenu) engine.ctx.peek('ui')?.pause?.();

  // Exhaustive compilation is useful for deterministic gates and powerful GPUs,
  // but on some ANGLE/D3D11 drivers it is itself the multi-minute "loading freeze".
  // Normal play therefore compiles the much smaller low/forward program set on its
  // first visible frames. Opt into the exhaustive diagnostic path with ?prewarm=1.
  if (config.prewarm === 'full') {
    setBootStep('prewarm', 'current');
    setBoot(
      'Shader werden vorbereitet …',
      0.82,
      'Shader-Modus: vollständig',
      'Shader werden einmalig zusammengestellt. Das kann je nach Grafiktreiber etwas dauern.'
    );
    warmup = await prewarm(engine, {
      onProgress: (progress) => setBoot(
        'Shader werden vorbereitet …',
        0.82 + progress * 0.15,
        'Shader-Modus: vollständig',
        'Shader werden einmalig zusammengestellt. Das kann je nach Grafiktreiber etwas dauern.'
      ),
    });

    if (warmup?.ok) {
      setBootStep('prewarm', 'done', { ms: warmup.ms });
      setBoot(
        'Shader sind vorbereitet',
        0.97,
        'Shader-Modus: vollständig',
        'Die Shader-Vorbereitung ist abgeschlossen.'
      );
    } else {
      setBootStep('prewarm', 'error', { stateText: 'Nicht verfügbar' });
      setBoot(
        'Shader-Vorbereitung nicht verfügbar',
        0.97,
        'Start wird ohne vollständiges Prewarm fortgesetzt',
        'Das Spiel startet trotzdem; einzelne Shader werden bei Bedarf vorbereitet.'
      );
    }
  } else {
    warmup = { ok: false, reason: 'production fast boot; use ?prewarm=1 to opt in' };
    setBootStep('prewarm', 'skipped', { stateText: 'Übersprungen – schneller Start' });
    setBoot(
      'Shader-Vorbereitung übersprungen',
      0.97,
      bootProfile,
      'Der schnelle Start ist aktiv; Shader werden bei Bedarf vorbereitet.'
    );
  }
  console.info('[boot] prewarm', warmup);
  window.__PREWARM__ = warmup;
  window.__ENGINE__ = engine;

  setBootStep('first-frame', 'current');
  setBoot(
    'Erster Frame wird dargestellt …',
    0.98,
    bootProfile,
    'Die Spielwelt wird jetzt eingeblendet.'
  );
  engine.start();
} catch (err) {
  console.error('[boot] startup failed', err);
  showBootError(err);
  throw err;
}

// Capture harness handshake: only flag ready once a frame has actually landed.
//
// BOOT_FRAMES is deliberately a frame COUNT, not a rAF race. In lockstep mode the
// engine has no loop of its own, so we hand-pump exactly this many frames and only
// then raise __READY__; the shot is therefore always applied at engine frame 3, no
// matter how long boot (or pre-warm) took in wall-clock terms.
const BOOT_FRAMES = 3;
if (lockstep) {
  // The DOM loading layer must never enter deterministic canvas screenshots.
  finishBoot(true);
  await shotApi.pump(BOOT_FRAMES);
  completeBootProgress();
  window.__READY__ = true;
} else {
  let warm = 0;
  const readyProbe = () => {
    if (++warm >= BOOT_FRAMES) {
      completeBootProgress();
      window.__READY__ = true;
      finishBoot(capture);
      return;
    }
    requestAnimationFrame(readyProbe);
  };
  requestAnimationFrame(readyProbe);
}

if (import.meta.hot) {
  import.meta.hot.dispose(() => engine.dispose());
}

import * as THREE from 'three';
import { installStyles, removeStyles } from './style.js';
import { el, clamp, clamp01, damp, setStyle } from './util.js';
import { Crosshair } from './crosshair.js';
import { Hitmarkers } from './hitmarkers.js';
import { DamageArcs } from './damage.js';
import { HealthFx } from './health.js';
import { AmmoPanel } from './ammo.js';
import { Killfeed } from './killfeed.js';
import { Compass, MatchBar } from './compass.js';
import { Minimap } from './minimap.js';
import { WorldMarkers } from './markers.js';
import { Prompt, Banner } from './prompts.js';
import { PauseMenu } from './menu.js';
import { CombatDemo } from './demo.js';

const MAX_BLIPS = 48;

/**
 * ===========================================================================
 * HUD / UI subsystem
 * ===========================================================================
 *
 * A DOM+CSS overlay (see style.js for the design system) driven entirely from
 * `lateUpdate`, after the camera has reached its final transform for the frame.
 * Nothing animates on a CSS keyframe or transition: every value is integrated
 * from `dt` here, which is what makes the capture harness deterministic and
 * lets the whole HUD freeze correctly when the game is paused.
 *
 * ---------------------------------------------------------------------------
 * PUBLIC API — `const ui = ctx.get('ui')`
 * ---------------------------------------------------------------------------
 *   ui.hitmarker(kind)                  'hit' | 'armour' | 'head' | 'kill'
 *   ui.damageNumber(worldPos, n, kind)  'hit' | 'hs' | 'armour' | 'kill'
 *   ui.hurt(amount, dirX, dirZ)         directional arc + flash + flinch
 *   ui.killfeed.push({attacker,victim,headshot,mine,attackerFriendly})
 *   ui.banner.show(title, sub, life)    kill / objective confirmation
 *   ui.setPrompt({key,text,sub,progress}) / ui.clearPrompt()
 *   ui.setObjectives([{position,label,name}])
 *   ui.setBlips([{x,z,kind:'enemy'|'friend',heading}])
 *   ui.spawnGrenade(worldPos, fuse)
 *   ui.setMatch({scoreUs,scoreThem,timeLeft,mode})
 *   ui.setHudVisible(bool)              hide everything (cinematics)
 *   ui.pause() / ui.resume() / ui.menu.toggle()
 *   ui.debugState('combat'|'menu'|'clean')
 *
 * ---------------------------------------------------------------------------
 * WHAT THIS SUBSYSTEM READS FROM OTHERS (all optional, all duck-typed)
 * ---------------------------------------------------------------------------
 *   weapons.getHudState() -> { name, mode, ammo, reserve, magSize, reloading,
 *                              reloadProgress, ads, spread, lethalCount,
 *                              tacticalCount }
 *   player.getHudState()  -> { health, maxHealth, armour, maxArmour, regen,
 *                              move, sprint, crouch, ads, airborne, position }
 *                            (or plain `player.health` / `player.position`)
 *   ai.getHudActors()     -> [{ position, alive, friendly, heading }]
 *   audio.playUi(id, gain) | audio.play(id) — hit ticks, heartbeat, warnings
 *
 * Events consumed: weapon:fire, weapon:reload, damage:dealt, damage:taken,
 * actor:death, player:state, explosion, resize.
 * Events emitted:  ui:pause, ui:quality-request, ui:quality,
 *                  ui:sensitivity, ui:fov, ui:setting.
 */
export class UiSystem {
  static id = 'ui';
  static deps = ['render'];

  async init(ctx) {
    this.ctx = ctx;
    this.rng = ctx.rng.fork();
    installStyles();

    const host = document.getElementById('ui') ?? document.body;
    this.root = el('div', 'ow-hud', host);

    // Stacking order: hurt overlays sit under the HUD, the menu over everything.
    this.hurtLayer = el('div', 'ow-layer', this.root);
    this.worldLayer = el('div', 'ow-layer', this.root);
    this.centreLayer = el('div', 'ow-layer', this.root);
    this.chromeLayer = el('div', 'ow-layer', this.root);

    this.health = new HealthFx(this.hurtLayer, this.chromeLayer);
    this.markers = new WorldMarkers(this.worldLayer, this.rng.fork());
    this.arcs = new DamageArcs(this.centreLayer);
    this.crosshair = new Crosshair(this.centreLayer);
    this.hit = new Hitmarkers(this.centreLayer);
    this.minimap = new Minimap(this.chromeLayer, this.rng.fork());
    this.compass = new Compass(this.chromeLayer);
    this.matchBar = new MatchBar(this.chromeLayer);
    this.killfeed = new Killfeed(this.chromeLayer);
    this.ammo = new AmmoPanel(this.chromeLayer);
    this.prompt = new Prompt(this.chromeLayer);
    this.banner = new Banner(this.chromeLayer);
    this.menu = new PauseMenu(this.root, ctx);

    this.health.onBeat = (i) => this.sfx('heartbeat', 0.35 + i * 0.5);

    /** Single source of truth for everything the HUD draws. */
    this.state = {
      health: 100,
      maxHealth: 100,
      armour: 0,
      maxArmour: 150,
      regen: false,
      ammo: 30,
      reserve: 210,
      magSize: 30,
      reloading: false,
      reloadProgress: 0,
      weaponName: 'M4A1',
      fireMode: 'AUTO',
      lethalCount: 2,
      tacticalCount: 1,
      move: 0,
      sprint: false,
      crouch: false,
      ads: false,
      airborne: false,
      baseSpread: 5.5,
      scoreUs: 0,
      scoreThem: 0,
      timeLeft: 600,
      mode: 'TDM',
      /** true when no player/weapons subsystem is driving us (stub-safe demo) */
      simulate: false,
      time: 0,
    };

    this.k = 1;
    this.vw = 1920;
    this.vh = 1080;
    this.hudVisible = 1;
    this.hudTarget = 1;
    this._lastRaw = ctx.time.raw;
    this._lastKillAt = -10;
    this._regenTimer = 0;
    this._wasPointerLocked = ctx.input.pointerLocked;
    this._bakeFrame = 0;

    // Escape is handled synchronously by Input so a Resume request still owns
    // the trusted key activation required by the Pointer Lock API.
    this._previousPauseHandler = ctx.input.onPause;
    this._onPauseRequest = () => {
      if (!ctx.input.frozen) this.menu.toggle();
      return true;
    };
    ctx.input.onPause = this._onPauseRequest;

    this._pos = new THREE.Vector3();
    this._prevPos = new THREE.Vector3();
    this._dir = new THREE.Vector3();
    this._tmp = new THREE.Vector3();
    this._objectives = [];
    this._compassObjs = [];
    this._blips = new Array(MAX_BLIPS);
    for (let i = 0; i < MAX_BLIPS; i++) this._blips[i] = { x: 0, z: 0, kind: 'enemy', heading: 0 };
    this._blipCount = 0;
    this._blipView = [];

    this.demo = null;

    this._unsubs = [];
    const on = (type, fn) => this._unsubs.push(ctx.events.on(type, fn));

    on('weapon:fire', (e) => {
      this.crosshair.onFire(e?.recoil ?? 1);
      if (this.state.simulate) return;
      const w = this._weaponState();
      if (!w) this.state.ammo = Math.max(0, this.state.ammo - 1);
    });

    on('weapon:reload', (e) => {
      const s = this.state;
      if (e?.phase === 'start') {
        s.reloading = true;
        s.reloadProgress = 0;
      } else if (e?.phase === 'end') {
        s.reloading = false;
        if (!this._weaponState()) {
          const take = Math.min(s.magSize - s.ammo, s.reserve);
          s.ammo += take;
          s.reserve -= take;
        }
      }
    });

    on('damage:dealt', (e) => {
      if (!e) return;
      // The payload means "damage dealt TO e.target". `ai` uses it for enemy
      // rounds that connect with the player, which must not draw a hitmarker or
      // a "YOU killed" killfeed row — that arrives as `damage:taken` below.
      if (this._isPlayerTarget(e.target)) return;
      const kind = e.killed ? 'kill' : e.headshot ? 'head' : e.armour ? 'armour' : 'hit';
      this.hitmarker(kind);
      if (e.point) {
        this.damageNumber(
          e.point,
          e.amount ?? 0,
          e.killed ? 'kill' : e.headshot ? 'hs' : e.armour ? 'armour' : 'hit'
        );
      }
      if (e.killed) {
        this._lastKillAt = ctx.time.elapsed;
        this.killfeed.push({
          attacker: 'YOU',
          victim: e.target?.name ?? e.name ?? 'ENEMY',
          headshot: !!e.headshot,
          mine: true,
        });
        this.banner.show('Enemy Eliminated', e.headshot ? '+150 XP · HEADSHOT' : '+100 XP');
        this.state.scoreUs++;
      }
    });

    on('damage:taken', (e) => {
      const amount = e?.amount ?? 10;
      if (e?.health !== undefined) this.state.health = e.health;
      else this.state.health = Math.max(0, this.state.health - amount);
      let dx = 0;
      let dz = 1;
      if (e?.from) {
        this._tmp.copy(e.from).sub(this._playerPos());
        dx = this._tmp.x;
        dz = this._tmp.z;
      }
      this.hurt(amount, dx, dz);
    });

    on('actor:death', (e) => {
      if (ctx.time.elapsed - this._lastKillAt < 0.3) return; // already credited
      this.killfeed.push({
        attacker: e?.by?.name ?? 'ENEMY',
        victim: e?.actor?.name ?? 'OPERATOR',
        attackerFriendly: false,
      });
    });

    on('explosion', (e) => {
      if (!e?.position) return;
      this._tmp.copy(e.position).sub(this._playerPos());
      const d = this._tmp.length();
      if (d < (e.radius ?? 6) * 2.5) this.crosshair.onFlinch(0.6);
    });

    on('player:state', (e) => {
      if (!e) return;
      const s = this.state;
      if (e.ads !== undefined) s.ads = !!e.ads;
      if (e.sprinting !== undefined) s.sprint = !!e.sprinting;
      if (e.stance !== undefined) s.crouch = e.stance === 'crouch' || e.stance === 'prone';
    });

    this.resize(ctx.canvas.clientWidth || innerWidth, ctx.canvas.clientHeight || innerHeight, ctx);
    this._prevPos.copy(this._playerPos());
  }

  /* ------------------------------------------------------------- helpers -- */

  _weaponState() {
    const w = this.ctx.peek('weapons');
    if (!w) return null;
    const s = typeof w.getHudState === 'function' ? w.getHudState() : w.hudState ?? null;
    return s && typeof s === 'object' ? s : null;
  }

  /** True when a `damage:dealt` payload is aimed at the local player. */
  _isPlayerTarget(t) {
    if (!t) return false;
    return t === 'player' || t === this.ctx.peek('player') || t.isPlayer === true;
  }

  _playerState() {
    const p = this.ctx.peek('player');
    if (!p) return null;
    const s = typeof p.getHudState === 'function' ? p.getHudState() : p.hudState ?? null;
    return s && typeof s === 'object' ? s : null;
  }

  _playerPos() {
    const p = this.ctx.peek('player');
    const pos = p?.position ?? p?.getPosition?.();
    if (pos && pos.isVector3) return this._pos.copy(pos);
    return this._pos.copy(this.ctx.camera.position);
  }

  /** Fire-and-forget audio; the audio subsystem may not exist yet. */
  sfx(id, gain = 1) {
    const a = this.ctx.peek('audio');
    if (!a) return;
    try {
      if (typeof a.playUi === 'function') a.playUi(id, gain);
      else if (typeof a.play === 'function') a.play(id, { gain });
      else if (typeof a.sfx === 'function') a.sfx(id, gain);
    } catch {
      /* audio is optional feedback — never let it break the HUD */
    }
  }

  /* ---------------------------------------------------------------- api --- */

  hitmarker(kind = 'hit') {
    this.hit.spawn(kind);
    this.crosshair.onHit();
    this.sfx(
      kind === 'kill' ? 'hit_kill' : kind === 'head' ? 'hit_head' : kind === 'armour' ? 'hit_armour' : 'hit_flesh',
      kind === 'kill' ? 1 : 0.7
    );
  }

  damageNumber(worldPos, amount, kind = 'hit') {
    this.markers.spawnDamage(worldPos, amount, kind);
  }

  /** Incoming damage: arc toward the source, screen flash, reticle flinch. */
  hurt(amount = 10, dirX = 0, dirZ = 1) {
    const i = clamp01(amount / 40);
    this.arcs.spawn(dirX, dirZ, 0.45 + i * 0.55);
    this.health.onDamage(i);
    this.crosshair.onFlinch(0.5 + i);
    this._regenTimer = 0;
    this.state.regen = false;
    this.sfx('player_hurt', 0.6 + i * 0.4);
  }

  setPrompt(p) {
    this.prompt.set(p);
  }

  clearPrompt() {
    this.prompt.clear();
  }

  setObjectives(list) {
    this._objectives = list ?? [];
  }

  addObjective(o) {
    this._objectives.push(o);
  }

  removeObjective(id) {
    const i = this._objectives.findIndex((o) => o.id === id);
    if (i >= 0) this._objectives.splice(i, 1);
  }

  /** Copies into a preallocated array — the caller's array is not retained. */
  setBlips(list) {
    const n = Math.min(list?.length ?? 0, MAX_BLIPS);
    for (let i = 0; i < n; i++) {
      const src = list[i];
      const dst = this._blips[i];
      dst.x = src.x ?? src.position?.x ?? 0;
      dst.z = src.z ?? src.position?.z ?? 0;
      dst.kind = src.kind ?? (src.friendly ? 'friend' : 'enemy');
      dst.heading = src.heading ?? 0;
    }
    this._blipCount = n;
  }

  spawnGrenade(worldPos, fuse = 2.4) {
    this.markers.spawnGrenade(worldPos, fuse);
    this.sfx('grenade_warn', 0.6);
  }

  setMatch(m) {
    Object.assign(this.state, m);
  }

  setHudVisible(v) {
    this.hudTarget = v ? 1 : 0;
  }

  pause() {
    this.menu.show();
  }

  resume() {
    this.menu.close();
  }

  /* --------------------------------------------------------------- debug -- */

  /**
   * Populate a representative state for screenshots / critics.
   * 'combat' runs the scripted firefight timeline in demo.js.
   */
  debugState(name = 'combat') {
    if (name === 'clean') {
      this.demo?.stop(this);
      this.demo = null;
      this.state.simulate = false;
      this.killfeed.clear();
      this.arcs.clear();
      this.hit.clear();
      this.markers.clear();
      this.clearPrompt();
      return { state: 'clean' };
    }
    if (name === 'menu') {
      this.debugState('combat');
      this.menu.show();
      return { state: 'menu' };
    }
    if (!this.demo) this.demo = new CombatDemo();
    this.demo.start(this);
    return { state: 'combat', frames: 'timeline keyed to frame 90' };
  }

  /* -------------------------------------------------------------- frame --- */

  lateUpdate(dt, ctx) {
    const t = ctx.time;
    const rawDt = clamp(t.raw - this._lastRaw, 0, 0.1);
    this._lastRaw = t.raw;
    const s = this.state;
    s.time = t.elapsed;

    // ---- pause -----------------------------------------------------------
    const pointerLocked = ctx.input.pointerLocked;
    if (
      ctx.input.enabled &&
      !ctx.input.frozen &&
      this._wasPointerLocked &&
      !pointerLocked &&
      !this.menu.open
    ) {
      // Browsers may reserve Escape while pointer-locked and emit only the
      // lock-loss event. Detect that single edge instead of retaining a stale
      // "was ever locked" flag that can reopen the menu after Resume.
      this.menu.show();
    }
    this._wasPointerLocked = pointerLocked;
    this.menu.update(rawDt);

    // ---- external state --------------------------------------------------
    // `simulate` means a scripted debug timeline owns the HUD numbers; letting
    // the live weapon/player state through would fight it every frame.
    const ws = s.simulate ? null : this._weaponState();
    if (ws) {
      if (ws.name) s.weaponName = ws.name;
      if (ws.mode) s.fireMode = ws.mode;
      if (ws.ammo !== undefined) s.ammo = ws.ammo;
      if (ws.reserve !== undefined) s.reserve = ws.reserve;
      if (ws.magSize !== undefined) s.magSize = ws.magSize;
      if (ws.reloading !== undefined) s.reloading = !!ws.reloading;
      if (ws.reloadProgress !== undefined) s.reloadProgress = ws.reloadProgress;
      if (ws.ads !== undefined) s.ads = !!ws.ads;
      if (ws.spread !== undefined) s.baseSpread = 4 + ws.spread * 40;
      if (ws.lethalCount !== undefined) s.lethalCount = ws.lethalCount;
      if (ws.tacticalCount !== undefined) s.tacticalCount = ws.tacticalCount;
    }

    const ps = s.simulate ? null : this._playerState();
    const player = ctx.peek('player');
    if (ps) {
      if (ps.health !== undefined) s.health = ps.health;
      if (ps.maxHealth !== undefined) s.maxHealth = ps.maxHealth;
      if (ps.armour !== undefined) s.armour = ps.armour;
      else if (ps.armor !== undefined) s.armour = ps.armor;
      if (ps.regen !== undefined) s.regen = !!ps.regen;
      if (ps.move !== undefined) s.move = ps.move;
      if (ps.sprint !== undefined) s.sprint = !!ps.sprint;
      if (ps.crouch !== undefined) s.crouch = !!ps.crouch;
      if (ps.ads !== undefined) s.ads = !!ps.ads;
      if (ps.airborne !== undefined) s.airborne = !!ps.airborne;
    } else if (player && typeof player.health === 'number') {
      s.health = player.health;
    }

    // ---- movement-derived reticle bloom (works with any player system) ----
    const pos = this._playerPos();
    if (!ps && !s.simulate) {
      this._dir.copy(pos).sub(this._prevPos);
      this._dir.y = 0;
      const speed = dt > 0 ? this._dir.length() / dt : 0;
      s.move = damp(s.move, clamp01(speed / 6.2), 12, Math.max(rawDt, 1e-3));
      if (!this._weaponState()) s.ads = ctx.input.ads && ctx.input.enabled;
    }
    this._prevPos.copy(pos);

    // ---- health regeneration when nobody else owns health ----------------
    if (!ps && !s.simulate && s.health < s.maxHealth) {
      this._regenTimer += dt;
      if (this._regenTimer > 4.5) {
        if (!s.regen) {
          s.regen = true;
          this.health.onRegenStart();
          this.sfx('regen', 0.4);
        }
        s.health = Math.min(s.maxHealth, s.health + dt * 24);
      }
    }

    // ---- demo timeline ---------------------------------------------------
    if (this.demo?.active) this.demo.update(this, dt);

    // ---- ai blips --------------------------------------------------------
    this._collectBlips();

    // ---- camera basis ----------------------------------------------------
    const m = ctx.camera.matrixWorld.elements;
    let rx = m[0];
    let rz = m[2];
    let fx = -m[8];
    let fz = -m[10];
    const rl = Math.hypot(rx, rz) || 1;
    const fl = Math.hypot(fx, fz) || 1;
    rx /= rl;
    rz /= rl;
    fx /= fl;
    fz /= fl;
    const heading = (Math.atan2(fx, -fz) * 180) / Math.PI;

    // ---- widgets ---------------------------------------------------------
    const hudGoal = this.hudTarget * (this.menu.open ? 0.15 : 1);
    this.hudVisible = damp(this.hudVisible, hudGoal, 10, rawDt);
    setStyle(this.chromeLayer, 'opacity', this.hudVisible.toFixed(3));
    setStyle(this.worldLayer, 'opacity', this.hudVisible.toFixed(3));
    setStyle(this.centreLayer, 'opacity', this.hudVisible.toFixed(3));

    this.crosshair.update(dt, s);
    this.hit.update(dt);
    this.arcs.update(dt, rx, rz, fx, fz);
    this.health.update(dt, s);
    this.ammo.update(dt, s);
    this.killfeed.update(dt);
    this.matchBar.update(s);
    this.prompt.update(dt);
    this.banner.update(dt);

    this._buildCompassObjectives(pos);
    this.compass.update(heading, this._compassObjs);

    this.markers.updateObjectives(this._objectives, ctx.camera, this.vw, this.vh, this.k);
    this.markers.updateGrenades(dt, ctx.camera, this.vw, this.vh, this.k);
    this.markers.updateDamage(dt, ctx.camera, this.vw, this.vh, this.k);

    // ---- minimap ---------------------------------------------------------
    if (!this.minimap.bakeDone && ++this._bakeFrame > 6 && this._bakeFrame % 20 === 0) {
      this.minimap.tryBake(ctx);
    }
    this._blipView.length = this._blipCount;
    for (let i = 0; i < this._blipCount; i++) this._blipView[i] = this._blips[i];
    this._mmState = this._mmState ?? { x: 0, z: 0, heading: 0, fov: 80, blips: null, objectives: null };
    this._mmState.x = pos.x;
    this._mmState.z = pos.z;
    this._mmState.heading = heading;
    this._mmState.fov = ctx.camera.fov;
    this._mmState.blips = this._blipView;
    this._mmState.objectives = this._mmObjs ?? (this._mmObjs = []);
    this._mmObjs.length = 0;
    for (const o of this._objectives) {
      if (!o.position) continue;
      this._mmObjs.push(o._mm ?? (o._mm = { x: 0, z: 0, label: o.label }));
      const last = this._mmObjs[this._mmObjs.length - 1];
      last.x = o.position.x;
      last.z = o.position.z;
      last.label = o.label;
    }
    this.minimap.draw(this._mmState);
  }

  _collectBlips() {
    if (this.demo?.active) return; // demo drives its own contacts
    const ai = this.ctx.peek('ai');
    const list = typeof ai?.getHudActors === 'function' ? ai.getHudActors() : ai?.actors ?? null;
    if (!Array.isArray(list)) return;
    let n = 0;
    for (let i = 0; i < list.length && n < MAX_BLIPS; i++) {
      const a = list[i];
      const p = a?.position ?? a?.pos;
      if (!p || a.alive === false || a.dead === true) continue;
      const b = this._blips[n++];
      b.x = p.x;
      b.z = p.z;
      b.kind = a.friendly ? 'friend' : 'enemy';
      b.heading = a.heading ?? (a.yaw !== undefined ? (a.yaw * 180) / Math.PI : 0);
    }
    this._blipCount = n;
  }

  _buildCompassObjectives(pos) {
    const out = this._compassObjs;
    out.length = 0;
    for (const o of this._objectives) {
      if (!o.position) continue;
      const dx = o.position.x - pos.x;
      const dz = o.position.z - pos.z;
      const bearing = (Math.atan2(dx, -dz) * 180) / Math.PI;
      out.push(o._cmp ?? (o._cmp = { bearing: 0, label: o.label, color: o.color }));
      const last = out[out.length - 1];
      last.bearing = bearing;
      last.label = o.label;
      last.color = o.color;
    }
    return out;
  }

  resize(w, h, ctx) {
    this.vw = w;
    this.vh = h;
    this.k = clamp(h / 1080, 0.62, 2.4);
    this.root.style.setProperty('--k', this.k.toFixed(4));
    this.crosshair.setScale(this.k);
    this.compass.setScale(this.k);
    this.minimap.resize(this.k);
  }

  dispose() {
    if (this.ctx.input.onPause === this._onPauseRequest) {
      this.ctx.input.onPause = this._previousPauseHandler ?? null;
    }
    for (const off of this._unsubs) off();
    this._unsubs.length = 0;
    this.crosshair.dispose();
    this.hit.dispose();
    this.arcs.dispose();
    this.health.dispose();
    this.ammo.dispose();
    this.killfeed.dispose();
    this.compass.dispose();
    this.matchBar.dispose();
    this.minimap.dispose();
    this.markers.dispose();
    this.prompt.dispose();
    this.banner.dispose();
    this.menu.dispose();
    this.root.remove();
    removeStyles();
  }
}

/**
 * Input aggregation: keyboard, mouse (pointer-locked), and gamepad, exposed as
 * a stable per-frame snapshot so gameplay never touches raw DOM events.
 *
 * Edge queries (`pressed`, `released`) are valid only during the frame in which
 * the transition happened — read them in update(), not fixedUpdate().
 */

export const ACTIONS = {
  forward: ['KeyW', 'ArrowUp'],
  back: ['KeyS', 'ArrowDown'],
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  jump: ['Space'],
  crouch: ['ControlLeft', 'KeyC'],
  prone: ['KeyZ'],
  sprint: ['ShiftLeft'],
  reload: ['KeyR'],
  use: ['KeyF'],
  melee: ['KeyV'],
  leanLeft: ['KeyQ'],
  leanRight: ['KeyE'],
  swapWeapon: ['Digit1', 'Digit2', 'Tab'],
  grenade: ['KeyG'],
  flashlight: ['KeyT'],
  pause: ['Escape'],
};

// Only keys actually consumed by gameplay may suppress a browser default.
// F11, refresh/devtools shortcuts and keyboard navigation must stay native.
const GAMEPLAY_CODES = new Set([
  ...Object.values(ACTIONS).flat(),
  'KeyB',
  'KeyI',
  'Digit3',
]);

export class Input {
  constructor(canvas, config) {
    this.canvas = canvas;
    this.config = config;

    this.down = new Set(); // codes currently held
    this._pressed = new Set(); // went down this frame
    this._released = new Set(); // went up this frame
    this._pendingDown = new Set();
    this._pendingUp = new Set();

    /** Accumulated pointer delta for this frame, in radians after sensitivity. */
    this.look = { x: 0, y: 0 };
    this._rawLook = { x: 0, y: 0 };
    this.wheel = 0;
    this._pendingWheel = 0;

    this.pointerLocked = false;
    this.enabled = true;
    /** Optional synchronous Escape handler installed by the UI subsystem. */
    this.onPause = null;
    /** Set true by capture mode so scripted shots aren't fought by real input. */
    this.frozen = false;

    this.gamepadIndex = null;
    this.stick = { moveX: 0, moveY: 0, lookX: 0, lookY: 0 };

    this._bound = {
      keydown: this._onKeyDown.bind(this),
      keyup: this._onKeyUp.bind(this),
      mousedown: this._onMouseDown.bind(this),
      mouseup: this._onMouseUp.bind(this),
      mousemove: this._onMouseMove.bind(this),
      wheel: this._onWheel.bind(this),
      lockchange: this._onLockChange.bind(this),
      blur: this._onBlur.bind(this),
      contextmenu: (e) => e.preventDefault(),
    };
  }

  attach() {
    addEventListener('keydown', this._bound.keydown);
    addEventListener('keyup', this._bound.keyup);
    addEventListener('mousedown', this._bound.mousedown);
    addEventListener('mouseup', this._bound.mouseup);
    addEventListener('mousemove', this._bound.mousemove);
    addEventListener('wheel', this._bound.wheel, { passive: true });
    addEventListener('blur', this._bound.blur);
    document.addEventListener('pointerlockchange', this._bound.lockchange);
    this.canvas.addEventListener('contextmenu', this._bound.contextmenu);
  }

  detach() {
    removeEventListener('keydown', this._bound.keydown);
    removeEventListener('keyup', this._bound.keyup);
    removeEventListener('mousedown', this._bound.mousedown);
    removeEventListener('mouseup', this._bound.mouseup);
    removeEventListener('mousemove', this._bound.mousemove);
    removeEventListener('wheel', this._bound.wheel);
    removeEventListener('blur', this._bound.blur);
    document.removeEventListener('pointerlockchange', this._bound.lockchange);
    this.canvas.removeEventListener('contextmenu', this._bound.contextmenu);
  }

  requestPointerLock() {
    if (document.pointerLockElement === this.canvas) return Promise.resolve(true);
    const request = this.canvas.requestPointerLock;
    if (typeof request !== 'function') return Promise.resolve(false);

    // Modern Chrome returns a promise. Convert rejection into `false` so callers
    // can keep the pause menu open instead of producing an unhandled page error.
    try {
      const result = request.call(this.canvas);
      if (result && typeof result.then === 'function') {
        return result.then(() => true, () => false);
      }
      // Legacy browsers return void after accepting the request.
      return Promise.resolve(true);
    } catch {
      return Promise.resolve(false);
    }
  }

  _onKeyDown(e) {
    if (!this.enabled || e.repeat) return;

    // Run Escape synchronously inside the trusted key event. That gives Resume
    // a valid user activation for requestPointerLock(), while pointer-lock loss
    // remains a fallback for browsers that reserve Escape and send no key event.
    if (e.code === 'Escape' && typeof this.onPause === 'function') {
      try {
        if (this.onPause(e) !== false) return;
      } catch (err) {
        console.error('[input] pause handler failed', err);
      }
    }

    if (!GAMEPLAY_CODES.has(e.code)) return;
    const fromControl = !!e.target?.closest?.('button, input, select, textarea, a[href], [contenteditable="true"]');
    const modifiedShortcut =
      (e.metaKey && !e.code.startsWith('Meta')) ||
      (e.ctrlKey && !e.code.startsWith('Control')) ||
      (e.altKey && !e.code.startsWith('Alt'));

    // While unlocked, keyboard input belongs to the pause menu/browser. In
    // particular, Tab and Space must continue to operate focused controls.
    if (fromControl || modifiedShortcut || (!this.pointerLocked && e.code !== 'Escape')) return;

    e.preventDefault();
    this._pendingDown.add(e.code);
  }

  _onKeyUp(e) {
    if (!this.enabled || !GAMEPLAY_CODES.has(e.code)) return;
    this._pendingUp.add(e.code);
  }

  _onMouseDown(e) {
    if (!this.enabled || (!this.pointerLocked && e.target !== this.canvas)) return;
    if (!this.pointerLocked && e.button === 0) this.requestPointerLock();
    this._pendingDown.add(`Mouse${e.button}`);
  }

  _onMouseUp(e) {
    if (!this.enabled || (!this.pointerLocked && e.target !== this.canvas)) return;
    this._pendingUp.add(`Mouse${e.button}`);
  }

  _onMouseMove(e) {
    if (!this.enabled || !this.pointerLocked || this.frozen) return;
    // movementX/Y is already relative and unaffected by cursor clamping.
    this._rawLook.x += e.movementX ?? 0;
    this._rawLook.y += e.movementY ?? 0;
  }

  _onWheel(e) {
    if (!this.enabled || (!this.pointerLocked && e.target !== this.canvas)) return;
    this._pendingWheel += Math.sign(e.deltaY);
  }

  _onLockChange() {
    this.pointerLocked = document.pointerLockElement === this.canvas;
    if (!this.pointerLocked) this._onBlur();
  }

  /** Losing focus must release every held key, or the player runs forever. */
  _onBlur() {
    for (const code of this.down) this._pendingUp.add(code);
    this._rawLook.x = 0;
    this._rawLook.y = 0;
  }

  beginFrame() {
    this._pressed.clear();
    this._released.clear();

    for (const code of this._pendingDown) {
      if (!this.down.has(code)) {
        this.down.add(code);
        this._pressed.add(code);
      }
    }
    for (const code of this._pendingUp) {
      if (this.down.delete(code)) this._released.add(code);
    }
    this._pendingDown.clear();
    this._pendingUp.clear();

    const s = this.config.sensitivity;
    this.look.x = this.frozen ? 0 : this._rawLook.x * s;
    this.look.y = this.frozen ? 0 : this._rawLook.y * s * (this.config.invertY ? -1 : 1);
    this._rawLook.x = 0;
    this._rawLook.y = 0;

    this.wheel = this._pendingWheel;
    this._pendingWheel = 0;

    this._pollGamepad();
  }

  endFrame() {}

  _pollGamepad() {
    const pads = navigator.getGamepads?.() ?? [];
    const pad = pads[this.gamepadIndex ?? 0] ?? pads.find(Boolean);
    if (!pad) {
      this.stick.moveX = this.stick.moveY = this.stick.lookX = this.stick.lookY = 0;
      return;
    }
    const dz = (v) => (Math.abs(v) < 0.16 ? 0 : (v - Math.sign(v) * 0.16) / 0.84);
    this.stick.moveX = dz(pad.axes[0] ?? 0);
    this.stick.moveY = dz(pad.axes[1] ?? 0);
    // Cubic response curve on the look stick — fine aim near centre, fast flicks at the edge.
    const curve = (v) => Math.sign(v) * Math.abs(v) ** 2.4;
    this.stick.lookX = curve(dz(pad.axes[2] ?? 0));
    this.stick.lookY = curve(dz(pad.axes[3] ?? 0));
  }

  /** True while any key bound to `action` is held. */
  action(name) {
    const codes = ACTIONS[name];
    if (!codes) return false;
    for (const c of codes) if (this.down.has(c)) return true;
    return false;
  }

  actionPressed(name) {
    const codes = ACTIONS[name];
    if (!codes) return false;
    for (const c of codes) if (this._pressed.has(c)) return true;
    return false;
  }

  held(code) {
    return this.down.has(code);
  }

  pressed(code) {
    return this._pressed.has(code);
  }

  released(code) {
    return this._released.has(code);
  }

  get fire() {
    return this.down.has('Mouse0');
  }

  get firePressed() {
    return this._pressed.has('Mouse0');
  }

  get ads() {
    return this.down.has('Mouse2');
  }

  /** Normalised WASD + left-stick movement, clamped to the unit disc so
   *  diagonals aren't faster than cardinals. */
  moveVector(out = { x: 0, y: 0 }) {
    let x = (this.action('right') ? 1 : 0) - (this.action('left') ? 1 : 0);
    let y = (this.action('forward') ? 1 : 0) - (this.action('back') ? 1 : 0);
    x += this.stick.moveX;
    y -= this.stick.moveY;
    const len = Math.hypot(x, y);
    if (len > 1) {
      x /= len;
      y /= len;
    }
    out.x = x;
    out.y = y;
    return out;
  }
}

